#!/bin/bash
#
# package() installs every file the device tree requests in the folders the package provides, each
# from the file in the OEM download it was matched to, and checks each one's SHA-256.
#
# Generated by bin/snapdragon-firmware-recipes with the PKGBUILD next to it; change the table or
# the generator, not this file.

set -euo pipefail

package_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT

fail() {
  echo "not ok - $1" >&2
  exit 1
}

source "$package_dir/PKGBUILD"
[[ " ${arch[*]} " == " aarch64 " ]] || fail "the package is aarch64-only"
[[ -z ${groups[*]:-} ]] || fail "the package is in no group, so only the machine it is for installs it"
[[ ${provides[*]} == 'qcom-firmware-glymur-hp-elitebook-x-g2q' ]] || fail "the package provides the firmware folders it fills"

# Each installed file, then the file in the unpacked OEM download it comes from.
files=(
  'qcom/glymur/hp/elitebook-x-g2q/adsp_dtbs.elf' 'hp-sp174694/src/driver/regrouped_driver/qcsubsys_ext_adsp8480/adsp_dtbs.elf'
  'qcom/glymur/hp/elitebook-x-g2q/adspr.jsn' 'hp-sp174694/src/driver/regrouped_driver/qcsubsys_ext_adsp8480/adspr.jsn'
  'qcom/glymur/hp/elitebook-x-g2q/adsps.jsn' 'hp-sp174694/src/driver/regrouped_driver/qcsubsys_ext_adsp8480/adsps.jsn'
  'qcom/glymur/hp/elitebook-x-g2q/adspua.jsn' 'hp-sp174694/src/driver/regrouped_driver/qcsubsys_ext_adsp8480/adspua.jsn'
  'qcom/glymur/hp/elitebook-x-g2q/cdsp_dtbs.elf' 'hp-sp174694/src/driver/regrouped_driver/qcnspmcdm8480/cdsp_dtbs.elf'
  'qcom/glymur/hp/elitebook-x-g2q/qcadsp8480.mbn' 'hp-sp174694/src/driver/regrouped_driver/qcsubsys_ext_adsp8480/qcadsp8480.mbn'
  'qcom/glymur/hp/elitebook-x-g2q/qccdsp8480.mbn' 'hp-sp174694/src/driver/regrouped_driver/qcnspmcdm8480/qccdsp8480.mbn'
  'qcom/glymur/hp/elitebook-x-g2q/soccpr.jsn' 'hp-sp174694/src/driver/regrouped_driver/qcsubsys_ext_soccp8480/soccpr.jsn'
)

# Stand in for the unpacked downloads, each file holding its own path.
srcdir="$scratch/src"
for ((i = 0; i < ${#files[@]}; i += 2)); do
  mkdir -p "$srcdir/$(dirname -- "${files[i + 1]}")"
  printf '%s\n' "${files[i + 1]}" >"$srcdir/${files[i + 1]}"
done
cp "$package_dir"/'hp,elitebook-x-g2q.list' "$srcdir/"

# The stand-ins cannot match the real SHA-256s, so record the list package() checks instead.
sha256sum() { cat >"$scratch/checked"; }

pkgdir="$scratch/pkg"
(cd "$srcdir" && package)

fw="$pkgdir/usr/lib/firmware"
for ((i = 0; i < ${#files[@]}; i += 2)); do
  [[ -f $fw/${files[i]} && $(<"$fw/${files[i]}") == "${files[i + 1]}" ]] ||
    fail "installs ${files[i + 1]} as ${files[i]}"
done
installed=$(cd "$fw" && find . -type f | sed 's|^\./||' | LC_ALL=C sort)
[[ $(wc -l <<<"$installed") -eq $((${#files[@]} / 2)) ]] || fail "installs only the files the device tree requests"
[[ $(awk '{print $2}' "$scratch/checked" | LC_ALL=C sort) == "$installed" ]] ||
  fail "checks every installed file against its SHA-256"
for folder in 'qcom/glymur/hp/elitebook-x-g2q'; do
  [[ -n $(find "$fw/$folder" -maxdepth 1 -type f) ]] || fail "fills $folder, which it provides"
done

list="$pkgdir/usr/share/qcom-firmware-extract/provided.d/"'hp,elitebook-x-g2q.list'
[[ -f $list ]] || fail "tells qcom-firmware-extract which firmware the board loads itself"
for f in 'qcom/glymur/hp/elitebook-x-g2q/soccp.mbn' 'qcom/glymur/hp/elitebook-x-g2q/soccp_dtb.mbn'; do
  grep -qxF "$f" "$list" || fail "lists $f as provided"
  [[ ! -e $fw/$f ]] || fail "leaves out $f, which the board loads itself"
done

echo "ok - hp-elitebook-x-g2q-firmware"
